function row(){const tr=document.createElement('tr');tr.innerHTML='<td class="idx"></td><td><input class="item" placeholder="품목명"></td><td><input class="spec" placeholder="규격"></td><td><select class="unit"><option>kg</option><option>EA</option><option>L</option></select></td><td><input class="qty" type="number" min="0" step="any" value="0"></td><td><input class="price" type="number" min="0" step="any" value="0"></td><td class="supply">0</td><td class="vat">0</td><td class="sum">0</td><td><button type="button" class="remove">삭제</button></td>';tr.addEventListener('input',calc);tr.querySelector('.remove').onclick=()=>{tr.remove();calc()};return tr}
function items(){return [...$('#npo-tbody').children].map(tr=>({item:tr.querySelector('.item').value.trim(),spec:tr.querySelector('.spec').value.trim(),unit:tr.querySelector('.unit').value,qty:num(tr.querySelector('.qty').value),unitPrice:num(tr.querySelector('.price').value)}))}
function calc(){let q=0,s=0,v=0;[...$('#npo-tbody').children].forEach((tr,i)=>{tr.querySelector('.idx').textContent=i+1;const x=items()[i],a=Math.round(x.qty*x.unitPrice),b=Math.round(a*.1);tr.querySelector('.supply').textContent=fmt(a);tr.querySelector('.vat').textContent=fmt(b);tr.querySelector('.sum').textContent=fmt(a+b);q+=x.qty;s+=a;v+=b});$('#npo-qty').textContent=fmt(q);$('#npo-supply').textContent=fmt(s);$('#npo-vat').textContent=fmt(v);$('#npo-sum').textContent=fmt(s+v)}
function value(n){return modal.querySelector('[name="'+n+'"]')?.value||''}
function collect(){return {purchaseNo:value('purchaseNo'),requisitionNo:value('requisitionNo'),orderDate:value('orderDate'),requestedDueDate:value('requestedDueDate'),supplier:value('supplier').trim(),status:value('status'),reason:value('reason'),notes:value('notes'),items:items()}}
